"use client";
import { useEffect, useRef, useState } from "react";
import Section from "./Section";
import { useLang } from "./LanguageProvider";
import { ui, carSpecs } from "@/data/content";

// Modelo 3D: coloque o arquivo em public/models/carro.glb (ou mude o caminho aqui)
const MODEL = "/models/carro.glb";

export default function Car3D() {
  const { t } = useLang();
  const ref = useRef<HTMLElement>(null);
  const [failed, setFailed] = useState(false);

  // carrega o web component só no navegador
  useEffect(() => { import("@google/model-viewer"); }, []);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const onError = () => setFailed(true);
    el.addEventListener("error", onError);
    return () => el.removeEventListener("error", onError);
  }, []);

  return (
    <Section id="car3d" title={t(ui.carTitle)}>
      <p className="font-display text-cyan tracking-widest text-sm">{t(ui.carTag).toUpperCase()}</p>
      <p className="mt-3 max-w-3xl text-muted leading-relaxed">{t(ui.carText)}</p>
      <div className="mt-8 grid grid-cols-2 lg:grid-cols-4 gap-4">
        {carSpecs.map((x) => (
          <div key={x.label.en} className="p-4 rounded-2xl bg-card/80 border border-cyan/30">
            <p className="font-display font-bold text-cyan text-lg leading-tight">{t(x.big)}</p>
            <p className="text-xs text-muted mt-2">{t(x.label)}</p>
          </div>))}
      </div>
      <div className="mt-6 p-5 rounded-2xl bg-card/60 border border-cyan/20 max-w-3xl">
        <h3 className="font-display font-bold text-sm text-cyan">{t(ui.carAeroTitle)}</h3>
        <p className="mt-2 text-sm text-muted">{t(ui.carAero)}</p>
      </div>
      <p className="mt-10 mb-4 text-muted text-sm">{t(ui.car3dText)}</p>
      <div className="w-full h-[55vh] rounded-3xl border border-cyan/30 bg-card/60 overflow-hidden">
        {failed ? (
          <div className="w-full h-full flex items-center justify-center text-muted text-sm">carro.glb</div>
        ) : (
          <model-viewer
            ref={ref}
            src={MODEL}
            alt="Carro da Vyperion Racing"
            camera-controls
            auto-rotate
            rotation-per-second="10deg"
            auto-rotate-delay="1500"
            interaction-prompt="none"
            disable-zoom
            touch-action="none"
            shadow-intensity="1"
            style={{ width: "100%", height: "100%", background: "transparent" }}
          />
        )}
      </div>
    </Section>);
}
