"use client";
import Img from "./Img";
import { darkLogos } from "@/data/images";
// Logo quadrado, mesmo tamanho para todos, com moldura fina.
export default function LogoTile({ name, src, link, size }: { name: string; src?: string; link: string; size: string }) {
  const dark = darkLogos.includes(name);
  return (
    <a href={link} aria-label={name}
      className={`${size} shrink-0 rounded-2xl p-1.5 flex items-center justify-center overflow-hidden ${dark ? "bg-card border border-cyan/40" : "bg-white"}`}>
      <Img src={src} alt={name} className="w-full h-full object-contain rounded-xl"
        fallback={<span className={`px-2 text-center text-xs font-bold ${dark ? "text-white" : "text-navy/70"}`}>{name}</span>} />
    </a>);
}
